&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; style=&quot;text-align: justify;&quot; data-block=&quot;true&quot; data-editor=&quot;8ung4&quot; data-offset-key=&quot;ekh65-0-0&quot;&gt;
